-- Start the demo: log STARTED, sync once, resume the sync task, the guard alert and all DTs.
insert into {{DEMO_DB}}.CONTROL.SCHEMA_CHANGE_LOG (SCENARIO, EVENT, GUARDRAIL, DETAIL, SOURCE)
values ('BASELINE', 'STARTED', null, 'Demo started: sync task, guard alert and Dynamic Tables running', 'PRESENTER');
call {{DEMO_L0}}.SYNC.SP_SYNC_L0();
alter dynamic table {{DEMO_DB}}.L2.DT_EQUIPMENT_DOWNTIME resume;
alter dynamic table {{DEMO_DB}}.L2.DT_SITE_SUMMARY resume;
alter dynamic table {{DEMO_DB}}.NAIVE.DT_DOWNTIME resume;
alter dynamic table {{DEMO_DB}}.NAIVE.DT_SITE_SUMMARY resume;
alter task {{DEMO_L0}}.SYNC.SYNC_L0 resume;
alter task {{DEMO_DB}}.CONTROL.STATUS_SNAPSHOT_TASK resume;
alter alert {{DEMO_DB}}.CONTROL.ALERT_SCHEMA_GUARD resume;
call {{DEMO_DB}}.CONTROL.SP_STATUS_SNAPSHOT();
select BANNER || ' / ' || CURRENT_SCENARIO from {{DEMO_DB}}.SERVING.V_STATUS;
